export const APP_ID = 'ifj26-table-maker'
export const DATA_VERSION = 1

export type Relation = '<' | '=' | '>'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "also make sure that the simulation input and state is also saved in the DB"
// Changes: Saved LL simulation state – current step (0-based) and speed index into the speed list.
export interface LLSimState {
  step: number
  speed: number
}

export interface ProjectData {
  app: typeof APP_ID
  version: number
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "also make sure that the simulation input and state is also saved in the DB"
  // Changes: Simulation state (current step and playback speed index) is stored with the input.
  ll: { grammar: string; input: string; sim: LLSimState }
  prec: {
    terminals: string[]
    cells: Record<string, Relation>
    rules: string
    input: string
    gen: { levels: string; ids: string; parens: string }
  }
  names: { map: string; ntPrefix: string; tPrefix: string; precPrefix: string }
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "could you add a tab where i will be able to define properties"
  // Changes: Formal definition G = (N, T, P, S): declared N and T (one symbol per line + note) and start S.
  def: { nonterminals: string; terminals: string; start: string }
}

export function defaultProjectData(): ProjectData {
  return {
    app: APP_ID,
    version: DATA_VERSION,
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "also make sure that the simulation input and state is also saved in the DB"
    // Changes: Simulation starts at the first step with 1× speed.
    ll: { grammar: '', input: '', sim: { step: 0, speed: 1 } },
    prec: { terminals: [], cells: {}, rules: '', input: '', gen: { levels: '', ids: '', parens: '' } },
    names: { map: '', ntPrefix: 'NT_', tPrefix: 'T_', precPrefix: 'PT_' },
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "could you add a tab where i will be able to define properties"
    // Changes: Empty definition by default (N, T and S are then derived from the rules).
    def: { nonterminals: '', terminals: '', start: '' },
  }
}

const text = (value: unknown, fallback = '') => (typeof value === 'string' ? value : fallback)

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "also make sure that the simulation input and state is also saved in the DB"
// Changes: Non-negative integer or the fallback.
const count = (value: unknown, fallback: number) =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0 ? value : fallback

const record = (value: unknown): Record<string, unknown> =>
  value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {}

export const isProjectFile = (raw: unknown) => record(raw).app === APP_ID

export function normalizeProjectData(raw: unknown): ProjectData {
  const d = defaultProjectData()
  const r = record(raw)
  const ll = record(r.ll)
  const sim = record(ll.sim)
  const prec = record(r.prec)
  const gen = record(prec.gen)
  const names = record(r.names)
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "could you add a tab where i will be able to define properties"
  // Changes: Read the grammar definition (older project files have none).
  const def = record(r.def)

  const terminals = Array.isArray(prec.terminals)
    ? [...new Set(prec.terminals.filter((t): t is string => typeof t === 'string' && t !== '' && t !== '$'))]
    : []
  const cells: Record<string, Relation> = {}
  for (const [key, value] of Object.entries(record(prec.cells))) {
    if (value === '<' || value === '=' || value === '>') cells[key] = value
  }

  return {
    app: APP_ID,
    version: DATA_VERSION,
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "also make sure that the simulation input and state is also saved in the DB"
    // Changes: Read the saved simulation state (older projects have none → defaults).
    ll: { grammar: text(ll.grammar), input: text(ll.input), sim: { step: count(sim.step, d.ll.sim.step), speed: count(sim.speed, d.ll.sim.speed) } },
    prec: {
      terminals,
      cells,
      rules: text(prec.rules),
      input: text(prec.input),
      gen: { levels: text(gen.levels), ids: text(gen.ids), parens: text(gen.parens) },
    },
    names: {
      map: text(names.map),
      ntPrefix: text(names.ntPrefix, d.names.ntPrefix),
      tPrefix: text(names.tPrefix, d.names.tPrefix),
      precPrefix: text(names.precPrefix, d.names.precPrefix),
    },
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "could you add a tab where i will be able to define properties"
    // Changes: Normalized grammar definition.
    def: { nonterminals: text(def.nonterminals), terminals: text(def.terminals), start: text(def.start).trim() },
  }
}
